function findAverage($arr) {
    if (!is_array($arr) || !isset($arr) || empty($arr)) {
        return "Error: Array is empty or not an array.";
    }

    $sum = 0;
    $count = 0;

    foreach ($arr as $value) {
        if (is_numeric($value)) {
            $sum += $value;
            $count++;
        } else {
            return "Error: Array contains non-numeric values.";
        }
    }

    if ($count === 0) {
        return "Error: Array is empty.";
    }

    return $sum / $count;
}
